CREATE TABLE `sys_menu` (
  `MENU_ID` bigint NOT NULL AUTO_INCREMENT,
  `MENU_NAME` varchar(200) NOT NULL,
  `PARENT_ID` decimal(19,0) DEFAULT '0',
  `ORDER_NUM` decimal(10,0) DEFAULT '0',
  `PATH` varchar(800) DEFAULT '',
  `COMPONENT` varchar(1020) DEFAULT NULL,
  `QUERY` varchar(1020) DEFAULT NULL,
  `ROUTE_NAME` varchar(200) DEFAULT '',
  `IS_FRAME` decimal(10,0) DEFAULT '1',
  `IS_CACHE` decimal(10,0) DEFAULT '0',
  `MENU_TYPE` char(4) DEFAULT '',
  `VISIBLE` char(4) DEFAULT '0',
  `STATUS` char(4) DEFAULT '0',
  `PERMS` varchar(400) DEFAULT NULL,
  `ICON` varchar(400) DEFAULT '#',
  `CREATE_BY` varchar(256) DEFAULT '',
  `CREATE_TIME` timestamp NULL DEFAULT NULL,
  `UPDATE_BY` varchar(256) DEFAULT '',
  `UPDATE_TIME` timestamp NULL DEFAULT NULL,
  `REMARK` text,
  `TYPE` varchar(10) DEFAULT NULL,
  PRIMARY KEY (`MENU_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
