--
-- Table structure for table `xfpt_after_sale`
--

DROP TABLE IF EXISTS `xfpt_after_sale`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `xfpt_after_sale` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `after_sale_no` varchar(64) NOT NULL COMMENT '售后单号',
  `order_id` bigint NOT NULL COMMENT '订单主表ID',
  `order_item_id` bigint DEFAULT NULL COMMENT '订单明细ID',
  `order_no` varchar(64) NOT NULL COMMENT '订单编号快照',
  `order_type` char(1) NOT NULL COMMENT '订单类型，1统购 2零售',
  `school_id` bigint DEFAULT NULL COMMENT '学校ID',
  `supplier_id` bigint NOT NULL COMMENT '供应商ID',
  `user_id` bigint NOT NULL COMMENT '发起用户ID',
  `user_name` varchar(100) NOT NULL COMMENT '发起用户名快照',
  `student_name` varchar(100) DEFAULT NULL COMMENT '学生姓名快照',
  `apply_type` char(1) NOT NULL COMMENT '申请类型，1仅退款 2退货退款 3换货',
  `target_size_id` bigint DEFAULT NULL COMMENT '换货目标尺码ID',
  `target_size_name` varchar(50) DEFAULT NULL COMMENT '换货目标尺码名称',
  `reason` varchar(500) DEFAULT NULL COMMENT '申请原因',
  `images_json` longtext COMMENT '图片凭证JSON文本',
  `apply_num` int NOT NULL DEFAULT '1' COMMENT '申请数量',
  `apply_amount` decimal(18,2) DEFAULT NULL COMMENT '申请金额',
  `actual_refund_amount` decimal(18,2) DEFAULT NULL COMMENT '实际退款金额',
  `refund_status` char(1) DEFAULT NULL COMMENT '退款状态，0未退款 1退款中 2退款成功 3退款失败',
  `refund_time` datetime DEFAULT NULL COMMENT '退款完成时间',
  `status` char(1) NOT NULL COMMENT '售后状态，0待审核 1已通过 2已驳回 3处理中 4已完成 5已关闭',
  `audit_by` varchar(64) DEFAULT NULL COMMENT '审核人',
  `audit_time` datetime DEFAULT NULL COMMENT '审核时间',
  `handle_result` varchar(500) DEFAULT NULL COMMENT '处理结果',
  `handle_remark` varchar(500) DEFAULT NULL COMMENT '处理备注',
  `finish_time` datetime DEFAULT NULL COMMENT '完成时间',
  `dept_id` bigint DEFAULT NULL COMMENT '当前归属部门/学校',
  `create_by` varchar(64) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `del_flag` char(1) NOT NULL DEFAULT '0' COMMENT '删除标记，0正常 1删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_xfpt_after_sale_no` (`after_sale_no`),
  KEY `idx_xfpt_after_sale_order` (`order_id`,`order_item_id`),
  KEY `idx_xfpt_after_sale_supplier` (`supplier_id`,`status`),
  KEY `idx_xfpt_after_sale_user` (`user_id`,`status`),
  KEY `idx_xfpt_after_sale_dept` (`dept_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='售后主表';
/*!40101 SET character_set_client = @saved_cs_client */;

