--
-- Table structure for table `xfpt_comment`
--

DROP TABLE IF EXISTS `xfpt_comment`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `xfpt_comment` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `order_id` bigint NOT NULL COMMENT '订单主表ID',
  `order_item_id` bigint DEFAULT NULL COMMENT '订单明细ID',
  `order_no` varchar(64) NOT NULL COMMENT '订单编号快照',
  `goods_id` bigint NOT NULL COMMENT '商品ID',
  `goods_name` varchar(200) NOT NULL COMMENT '商品名称快照',
  `user_id` bigint NOT NULL COMMENT '评价用户ID',
  `user_name` varchar(100) NOT NULL COMMENT '评价用户名快照',
  `supplier_id` bigint NOT NULL COMMENT '供应商ID',
  `score` tinyint(1) NOT NULL COMMENT '评分，1-5分',
  `content` text COMMENT '评价内容',
  `images_json` longtext COMMENT '评价图片JSON文本',
  `reply_content` text COMMENT '历史商家回复内容，后续回复使用xfpt_comment_reply',
  `reply_time` datetime DEFAULT NULL COMMENT '历史商家回复时间',
  `status` char(1) NOT NULL DEFAULT '0' COMMENT '评价状态，0正常 1隐藏',
  `create_by` varchar(64) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `del_flag` char(1) NOT NULL DEFAULT '0' COMMENT '删除标记，0正常 1删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_xfpt_comment_order_item_user` (`order_item_id`,`user_id`),
  KEY `idx_xfpt_comment_order` (`order_id`),
  KEY `idx_xfpt_comment_goods` (`goods_id`),
  KEY `idx_xfpt_comment_supplier` (`supplier_id`,`status`),
  KEY `idx_xfpt_comment_user` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='商品评价';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `xfpt_comment`
--

LOCK TABLES `xfpt_comment` WRITE;
/*!40000 ALTER TABLE `xfpt_comment` DISABLE KEYS */;
INSERT INTO `xfpt_comment` VALUES (1,4,4,'DEMO-ORDER-20260504185529-2-46-4',4,'校园运动鞋',42,'李蒙莎',8,5,'面料厚实，尺码合适，孩子穿着舒适。','[\"/profile/upload/demo/comment.jpg\"]','感谢您的评价。','2026-05-04 20:55:30','0','admin','2026-05-04 18:55:30',NULL,NULL,'测试评价','0'),(2,3,3,'DEMO-ORDER-20260504185529-2-42-3',3,'冬季加绒冲锋衣校服',38,'魏鹏远',2,4,'发货速度可以，袖口做工还需要再细一点。','[\"/profile/upload/demo/comment.jpg\"]','感谢您的评价。','2026-05-04 20:55:30','0','admin','2026-05-04 18:55:30',NULL,NULL,'测试评价','0');
/*!40000 ALTER TABLE `xfpt_comment` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `xfpt_comment_reply`
--

DROP TABLE IF EXISTS `xfpt_comment_reply`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `xfpt_comment_reply` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `comment_id` bigint NOT NULL COMMENT '所属评论ID',
  `order_id` bigint DEFAULT NULL COMMENT '订单ID',
  `order_item_id` bigint DEFAULT NULL COMMENT '订单明细ID',
  `goods_id` bigint DEFAULT NULL COMMENT '商品ID',
  `supplier_id` bigint DEFAULT NULL COMMENT '供应商ID',
  `from_user_id` bigint NOT NULL COMMENT '回复人ID',
  `from_user_name` varchar(100) NOT NULL COMMENT '回复人姓名快照',
  `from_role_type` char(1) NOT NULL COMMENT '回复人角色，1家长 2供应商',
  `from_role_title` varchar(20) NOT NULL COMMENT '回复人角色标题快照',
  `to_user_id` bigint DEFAULT NULL COMMENT '被回复人ID',
  `to_user_name` varchar(100) DEFAULT NULL COMMENT '被回复人姓名快照',
  `to_role_type` char(1) DEFAULT NULL COMMENT '被回复人角色，1家长 2供应商',
  `to_role_title` varchar(20) DEFAULT NULL COMMENT '被回复人角色标题快照',
  `content` text COMMENT '回复内容',
  `status` char(1) NOT NULL COMMENT '状态，0正常 1隐藏',
  `sort_num` int DEFAULT NULL COMMENT '排序值',
  `create_by` varchar(64) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `del_flag` char(1) NOT NULL DEFAULT '0' COMMENT '删除标记，0正常 1删除',
  PRIMARY KEY (`id`),
  KEY `idx_xfpt_comment_reply_comment` (`comment_id`,`create_time`),
  KEY `idx_xfpt_comment_reply_order_item` (`order_item_id`,`create_time`),
  KEY `idx_xfpt_comment_reply_from_user` (`from_user_id`),
  KEY `idx_xfpt_comment_reply_supplier` (`supplier_id`),
  KEY `idx_xfpt_comment_reply_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='商品评论回复';
/*!40101 SET character_set_client = @saved_cs_client */;

