DROP TABLE IF EXISTS `xfpt_order_info`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `xfpt_order_info` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `order_no` varchar(64) NOT NULL COMMENT '订单号',
  `order_type` char(1) NOT NULL COMMENT '订单类型，1统购 2零售',
  `notice_id` bigint DEFAULT NULL COMMENT '统购公告ID',
  `school_id` bigint DEFAULT NULL COMMENT '学校ID',
  `school_name` varchar(200) DEFAULT NULL COMMENT '学校名称快照',
  `supplier_id` bigint NOT NULL COMMENT '供应商ID',
  `supplier_name` varchar(200) NOT NULL COMMENT '供应商名称快照',
  `user_id` bigint NOT NULL COMMENT '下单用户ID',
