  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `del_flag` char(1) NOT NULL DEFAULT '0' COMMENT '删除标记，0正常 1删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_xfpt_production_order_no` (`production_no`),
  KEY `idx_xfpt_production_order_notice` (`notice_id`),
  KEY `idx_xfpt_production_order_order` (`order_id`),
  KEY `idx_xfpt_production_order_supplier` (`supplier_id`),
  KEY `idx_xfpt_production_order_status` (`status`),
  KEY `idx_xfpt_production_order_dept` (`dept_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='生产单';
