DROP TABLE IF EXISTS `xfpt_questionnaire_config`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `xfpt_questionnaire_config` (
  `ID` bigint NOT NULL AUTO_INCREMENT,
  `TITLE` varchar(200) NOT NULL,
  `USE_STATUS` decimal(10,0) NOT NULL DEFAULT '1',
  `CREATE_BY` varchar(100) DEFAULT NULL,
  `CREATE_TIME` datetime DEFAULT NULL,
  `UPDATE_BY` varchar(100) DEFAULT NULL,
  `UPDATE_TIME` datetime DEFAULT NULL,
  `REMARK` varchar(1000) DEFAULT NULL,
  `DEL_FLAG` char(10) DEFAULT '0',
  `CATEGORY` varchar(19) DEFAULT '0',
  `FB_STATUS` decimal(19,0) DEFAULT '0',
  `BEGIN_TIME` datetime DEFAULT NULL,
  `END_TIME` datetime DEFAULT NULL,
  `TYPE` varchar(100) DEFAULT NULL,
  `DEPT_ID` decimal(19,0) DEFAULT NULL,
  `ANCESTORS` varchar(100) DEFAULT NULL,
  `WJ_STATUS` varchar(100) DEFAULT NULL,
  `VOTING_DESCRIPTION` text,
  `VOTING_NOTICE` text,
  `NAMES` text,
  `LC_CATEGORY` varchar(40) DEFAULT NULL,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='问卷调查主配置表';
