INSERT INTO `xfpt_questionnaire_config` VALUES (208,'家长购买意见模版',1,'管理员','2025-08-07 17:00:26',NULL,NULL,NULL,'0','0',0,NULL,NULL,'1',100,'0',NULL,NULL,NULL,NULL,'0'),(209,'家长满意度调查',1,'管理员','2025-08-07 17:06:25',NULL,NULL,NULL,'0','0',0,NULL,NULL,'2',100,'0',NULL,NULL,NULL,NULL,'0'),(257,'测试',1,'石家庄市第113中学','2025-08-13 10:32:43',NULL,NULL,NULL,'0','2',1,'2025-08-13 02:32:03','2025-08-20 02:32:03','1',552,'0,100,201',NULL,NULL,'<p>尊敬的家长:</p><p class=\"ql-indent-1\">您好!感谢长期以来对我校工作的理解和支持。正是由于您的配合与支持,我校的各方面工作才得以顺利完成。为了进一步规范学校管理,展示我校校风校貌,激发学生集体荣誉感,消除学生攀比心理,便于学校组织的集体活动和学生的安全管理。经学校班子会研究决定,按照家长自愿原则,现向所有家长征集校服采购意见。关于征订校服学校会组建由家长委员会代表、教师代表、学校管理人员、社会代表、学生代表、家长代表等六方代表组成的选用组织,负责校服选用、采购、监督工作。关于校服企业,学校会根据在校学生人数选取合理比例的学生、教师、家长代表共同组成评定组进行甄选确定。学校将尽最大努力让学生、家长满意。请您在页面下方填写信息并勾选“同意”或“不同意”,感谢您的配合。</p>','张三,李四,王五,赵六','1'),(258,'测试意见征集',1,'演示账号','2025-08-13 17:40:52',NULL,NULL,NULL,'0','2',1,'2025-08-13 09:39:47','2025-08-20 09:39:47','1',378,'0,100,200',NULL,NULL,'<p>尊敬的家长:</p><p class=\"ql-indent-1\">您好!感谢长期以来对我校工作的理解和支持。正是由于您的配合与支持,我校的各方面工作才得以顺利完成。为了进一步规范学校管理,展示我校校风校貌,激发学生集体荣誉感,消除学生攀比心理,便于学校组织的集体活动和学生的安全管理。经学校班子会研究决定,按照家长自愿原则,现向所有家长征集校服采购意见。关于征订校服学校会组建由家长委员会代表、教师代表、学校管理人员、社会代表、学生代表、家长代表等六方代表组成的选用组织,负责校服选用、采购、监督工作。关于校服企业,学校会根据在校学生人数选取合理比例的学生、教师、家长代表共同组成评定组进行甄选确定。学校将尽最大努力让学生、家长满意。请您在页面下方填写信息并勾选“同意”或“不同意”,感谢您的配合。</p>','张三,李四,王五','1'),(263,'测试',1,'演示账号','2025-08-14 16:11:56',NULL,NULL,NULL,'0','3',1,'2025-08-21 16:11:23','2025-08-28 16:11:23','4',378,'0,100,200',NULL,'[{\"createBy\":\"演示账号\",\"createTime\":\"2025-08-14 11:47:46\",\"updateBy\":null,\"updateTime\":null,\"remark\":\"68\",\"delFlag\":\"0\",\"id\":217,\"name\":\"企业一\",\"price\":null,\"file\":\"/statics/2025/08/14/GB 31701-2015 婴幼儿及儿童纺织产品安全技术规范_20250814114328A034.pdf\",\"modeId\":\"33\",\"deptId\":378,\"ancestors\":\"0,100,200\",\"videoUrl\":\"\",\"url\":\"\"},{\"createBy\":\"演示账号\",\"createTime\":\"2025-08-14 13:46:29\",\"updateBy\":null,\"updateTime\":null,\"remark\":\"68\",\"delFlag\":\"0\",\"id\":221,\"name\":\"企业二\",\"price\":n