DROP TABLE IF EXISTS `xfpt_school_message`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `xfpt_school_message` (
  `ID` bigint NOT NULL,
  `DEPT_ID` decimal(19,0) DEFAULT NULL,
  `SCHOOL_NAME` varchar(100) DEFAULT NULL,
  `ACADEMY_TYPE` varchar(100) DEFAULT NULL,
  `REGION_PROVINCE` varchar(100) DEFAULT NULL,
  `REGION_CITY` varchar(100) DEFAULT NULL,
  `REGION_COUNTY` varchar(100) DEFAULT NULL,
  `DETAILED_ADDRESS` varchar(100) DEFAULT NULL,
  `SCHOOL_TYPE` int DEFAULT NULL,
  `SCHOOL_BADGE` varchar(100) DEFAULT NULL,
  `CREATE_BY` varchar(100) DEFAULT NULL,
  `CREATE_TIME` timestamp NULL DEFAULT NULL,
  `UPDATE_BY` varchar(100) DEFAULT NULL,
  `UPDATE_TIME` timestamp NULL DEFAULT NULL,
  `REMARK` text,
  `DEL_FLAG` varchar(100) DEFAULT NULL,
  `SCHOOL_AREA` varchar(100) DEFAULT NULL,
  `PRINCIPAL_NAME` varchar(100) DEFAULT NULL,
  `PRINCIPAL_PHONE` varchar(100) DEFAULT NULL,
  `bank_account_name` varchar(100) DEFAULT NULL COMMENT '银行账户户名',
  `bank_name` varchar(100) DEFAULT NULL COMMENT '开户银行',
  `bank_branch_name` varchar(200) DEFAULT NULL COMMENT '开户支行',
  `bank_account_no` varchar(64) DEFAULT NULL COMMENT '银行卡号',
  `AREA` decimal(19,0) DEFAULT NULL,
  `people_count` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='学校信息';
