INSERT INTO `xfpt_school_message` VALUES (20,442,'石家庄市麒麟小学','1',NULL,'石家庄市麒麟小学','桥西区','石家庄市麒麟小学',2,'','石家庄麒麟小学','2025-05-15 19:42:12','石家庄麒麟小学','2025-09-01 11:42:38',NULL,'0','0','11','13028688381',NULL,NULL,NULL,NULL,200,NULL),(26,552,'石家庄市第113中学','1',NULL,'石家庄市','长安区','CES ',1,'','石家庄市第113中学','2025-08-13 16:54:48',NULL,NULL,NULL,'0','','张三','13028688888',NULL,NULL,NULL,NULL,101,NULL),(31,230,'石家庄财经商贸学校','2',NULL,'石家庄市','市直学校','太行北大街39号正定职教园区',0,'/filestatics/2025/09/08/校徽_20250908090450A271.jpg','石家庄财经商贸学校','2025-08-28 08:21:17','石家庄财经商贸学校','2025-09-08 09:09:38',' 石家庄财经商贸学校，是一所国办全日制中等职业学校，2018年6月，在整合原石家庄市职业财会学校资源的基础上成立，已有60余年的办学历史，2018年10月搬迁入驻石家庄市职业教育园区（正定新区），2019年5月，石家庄经济学校整体并入。\n\n        学校坐落于石家庄市正定新区太行北大街39号，占地面积153460平方米，建筑面积113398平方米，设计在校生规模6500人，主要建筑有教学楼8栋、学生公寓4栋、办公楼、实训楼、综合楼、后勤服务楼各1栋，图书馆、阅览室、音乐厅、排练厅、学术报告厅、多功能报告厅、演播室、录播室、阶梯教室、书画教室、音乐教室、科技活动室、公共机房、风雨操场、标准化运动场等辅助设施完备，并与园区共享图书信息中心、会议中心、体育馆、游泳馆、艺术馆、公共实训基地、双创科技园等公共设施。\n\n        学校是国家职业教育提质培优行动计划双优项目建设单位，河北省中等职业教育质量提升工程精品学校，河北省文明单位，河北省文明校园。\n\n        学校办学定位为“服务区域经济社会发展，立足石家庄，服务京津冀”，专业建设和发展定位以中等职业学校“财经商贸”大类和“食品药品与粮食”大类为主，兼顾社会紧缺专业的其他大类。形成了以“会计事务”“金融事务”“电子商务”“跨境电子商务”“制药技术应用”“市场营销”“物流服务与管理”“生物制药工艺”8个省级骨干特色专业为龙头的“财经”“商贸”“制药”“物流”等四大专业群。\n\n        目前开设会计事务、纳税事务、法律事务、电子商务、跨境电子商务、网络营销、物流服务与管理（无人机方向）、制药技术应用、生物制药工艺、分析检验技术、市场营销、运动训练、计算机网络技术等13个三年制普通中专专业，以及会计事务、金融事务、电子商务、跨境电子商务、制药技术应用、航空服务6个“3+2”中高职衔接专业。\n\n        学校坚持“立德树人、服务发展、促进就业”的办学宗旨，秉承“人人皆可成才，人人尽展其才”的教育理念，强化“爱岗、爱校、爱生、爱己，敬业、奉献、笃信、追求”的师德师风建设，潜心培育“升学有基础、就业有优势、创业有本领、发展有潜力”的优秀中职毕业生，紧紧围绕创建“双优”学校目标，全力推进内涵建设、质量提升、创新发展。','0','','张红云','13131113801',NULL,NULL,NULL,NULL,204,NULL),(32,238,'河北辛集中学','1',NULL,'石家庄市','市直学校','河北省辛集市辛中南路1号',0,'/filestatics/2025/08/28/河北辛集中学校徽定稿_20250828082116A065.png','河北辛集中学','2025-08-28 08:21:25',NULL,NULL,NULL,'0','','李丰','13832383034',NULL,NULL,NULL,NULL,204,NULL),(33,242,'石家庄实验中学','1',NULL,'石家庄市','市直学校','无新路5号石家庄实验中学',0,'','石家庄实验中学','2025-08-28 08:54:34','石家庄实验中学','2025-08-28 08:55:50',NULL,'0','','王悦锋','13933850251',NULL,NULL,NULL,NULL,204,NULL),(34,2036,'元氏县第一中学','1',NULL,'石家庄市','元氏县','元氏县常山路145号',0,'/filestatics/2025/11/03/校徽_20251103151233A838.jpg','元氏一中','2025-08-28 09:02:52','元氏一中','2025-11-03 15:15:31','元氏县第一中学源自于宋仁宗皇祐元年(1049年)的元氏县学,距今976年。自宋肇始，历经宋、元、明、清、民国五代，元氏一中历来为县级最高学府，薪火相传，弦歌不辍，是文脉绵延至今的千年学府。1952年9月，在旧城文庙学宫的旧址上建立了现代意义的中学——“元氏县初级中学”，1978年1月，命名为“元氏县第一中学”，2003年9月整体搬迁到现址，2004年3月被命名为省级示范性高中。','0','','王银波','14730491797',NULL,NULL,NULL,NULL,218,'3171'),(35,642,'石家庄外国语学校','1',NULL,'石家庄市','市直学校','河北省裕华区育才街318号',1,'','石家庄外国语学校','2025-08-28 09:07:28',NULL,NULL,NULL,'0','','王苗','13833118275',NULL,NULL,NULL,NULL,204,NULL),(36,1132,'石家庄市鹿泉区凤凰外国语学校','1',NULL,'石家庄市','鹿泉区','石家庄市鹿泉区山前大道49号',4,'/filestatics/2025/08/28/凤凰logo_20250828092346A066.png','石家庄市鹿泉区凤凰外国语学校','2025-08-28 09:25:29',NULL,NULL,NULL,'0','','张莎','13131155217',NULL,NULL,NULL,NULL,211,NULL),(37,1442,'石家庄市栾城区祥和路小学','1',NULL,'石家庄市','栾城区','栾城区栾城镇韩家庄村祥和路216号',2,'','祥和路小学','2025-08-28 09:26:52',NULL,NULL,NULL,'0','','赵文杰','13700315027',NULL,NULL,NULL,NULL,212,NULL),(38,2153,'石家庄精英中学小学部','1',NULL,'石家庄市','高新区','高新区学苑路25号',2,'','石家庄精英小学部','2025-08-28 09:30:22','石家庄精英小学部','2025-08-28 09:31:01',NULL,'0','','郭闪','18131165561',NULL,NULL,NULL,NULL,205,NULL),(39,1257,'井陉县职业技术教育中心','2',NULL,'石家庄市','井陉县','井陉县西山南路1号',0,'','井陉县职业技术教育中心','2025-08-28 09:51:04',NULL,NULL,NULL,'0','','高国良','18233114546',NULL,NULL,NULL,NULL,209,NULL),(40,2193,'石家庄一中实验学校','1',NULL,'石家庄市','高新区','湘江道3号',0,'','石家庄一中实验学校','2025-08-28 10:14:39',NULL,NULL,NULL,'0','','吉浩志','18031105547',NULL,NULL,NULL,NULL,205,NULL),(41,2032,'元氏县职业技术教育中心','2',NULL,'石家庄市','元氏县','东张乡滨河大道126号',4,'/filestatics/2025/08/28/校徽_20250828102724A069.jpg','元氏县职业技术教育中心','2025-08-28 10:29:13','元氏县职业技术教育中心','2025-08-28 10:35:55',NULL,'0','','远剑勇','15230865166',NULL,NULL,NULL,NULL,218,NULL),(42,2040,'ces','1',NULL,'石家庄市','赵县','赵县',3,'','田庄学校','2025-08-28 10:31:58',NULL,NULL,NULL,'0','','1','15127116174',NULL,NULL,NULL,NULL,220,NULL),(43,1373,'石家庄弘文中学','1',NULL,'石家庄市','正定县','正定县燕赵北大街教场路81号',4,'/filestatics/2025/08/28/校徽_20250828104100A072.png','正定县弘文中学','2025-08-28 10:41:10','正定县弘文中学','2025-08-28 10:45:12',NULL,'0','','赵芝林','15031489078',NULL,NULL,NULL,NULL,221,NULL),(44,239,'河北正中实验中学','1',NULL,'石家庄市','市直学校','石家庄市正定县恒山东路190号',0,'','河北正中实验中学','2025-08-28 11:21:47','河北正中实验中学','2025-08-28 11:24:54',NULL,'0','','高志英','13933171051',NULL,NULL,NULL,NULL,204,NULL),(45,247,'河北正定中学','1',NULL,'石家庄市','正定县','正定镇府西街80号',0,'/filestatics/2025/08/28/2-河北正定中学校徽jpg_20250828113224A076.jpg','河北正定中学','2025-08-28 11:30:19','河北正定中学','2025-08-28 11:32:32',NULL,'0','','孙吉林','13831106468',NULL,NULL,NULL,NULL,221,NULL),(46,231,'石家庄电子信息学校','2',NULL,'石家庄市','市直学校','正定县诸福屯镇华阳路21号',0,'/filestatics/2025/08/28/f58eecb9bb20266aea53ad8c4232d500_20250828115007A078.png','石家庄电子信息学校','2025-08-28 11:50:47','石家庄电子信息学校','2025-10-23 14:45:51','石家庄电子信息学校是石家庄市教育局直属的、以电子信息技术为特色的省级重点职业学校。','0','','张海丽','13785188102',NULL,NULL,NULL,NULL,204,NULL),(47,2206,'石家庄市长安区华文学校','1',NULL,'石家庄市','长安区','石家庄市长安区胜利北大街293号',4,'/filestatics/2025/09/03/校徽_20250903132956A049.jpg','石家庄市长安区华文学校','2025-08-28 13:53:06','石家庄市长安区华文学校','2025-09-03 13:30:12','石家庄华文学校是一所现代化九年一贯制寄宿学校，占地面积25亩，建筑面积15000平米。学校位于市区北部核心商业区胜利北大街293号，地理位置优越，购物、医疗、教育等生活配套设施完善，紧邻北二环，交通便利，地铁2号线和多趟公交线路均可直达。开办以来坚持贯彻党的教育方针，全面实施素质教育。2024年9月起，小学部又聘请了原水源街教学校长刘东培全面接手小学部；中学部聘请了特级教官配合教育教学着力打造高标准、寄宿制、半军事化管理的现代化、新优质学校。让每一名学生享有公平而有质量、理性而有温度的教育，全面而有个性的发展。','0','','席晓洁','18233154953',NULL,NULL,NULL,NULL,101,NULL),(48,2195,'石家庄精英中学','1',NULL,'石家庄市','高新区','石家庄市高新区学院路25号',0,'','石家庄精英中学','2025-08-28 14:24:31','石家庄精英中学','2025-08-28 14:44:23',NULL,'0','','高吉成','18932947976',NULL,NULL,NULL,NULL,205,NULL),(49,1451,'石家庄市栾城区南高乡中学','1',NULL,'石家庄市','栾城区','南高村',1,'','石家庄市栾城区南高乡中学','2025-08-28 14:25:41','石家庄市栾城区南高乡中学','2025-08-28 14:25:54',NULL,'0','','李金虎','13463671223',NULL,NULL,NULL,NULL,212,NULL),(50,2211,'石家庄精英中学初中部','1',NULL,'石家庄市','高新区','学苑路25号',1,'/filestatics/2025/08/28/979ef49ef6f42a4f58012634b309061_20250828145339A083.jpg','石家庄精英中学初中部','2025-08-28 14:53:48','石家庄精英中学初中部','2025-08-28 14:54:10',NULL,'0','','梁博英',