--
-- Table structure for table `xfpt_supplier_apply`
--

DROP TABLE IF EXISTS `xfpt_supplier_apply`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `xfpt_supplier_apply` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `notice_id` bigint NOT NULL COMMENT '公告ID',
  `school_id` bigint NOT NULL COMMENT '学校ID',
  `supplier_id` bigint NOT NULL COMMENT '供应商ID',
  `supplier_name` varchar(200) NOT NULL COMMENT '供应商名称快照',
  `apply_no` varchar(64) NOT NULL COMMENT '报名单号',
  `apply_status` char(1) NOT NULL COMMENT '报名状态，0待提交 1已提交 2已撤回',
  `qualification_status` char(1) NOT NULL COMMENT '资质审查状态，0待审查 1通过 2不通过',
  `bid_stage_status` char(1) DEFAULT NULL COMMENT '比选阶段状态，0未进入 1已进入 2已完成',
  `bid_result_status` char(1) DEFAULT NULL COMMENT '比选结果状态，0未出结果 1已中选 2未中选',
  `apply_time` datetime DEFAULT NULL COMMENT '报名时间',
  `audit_time` datetime DEFAULT NULL COMMENT '审核时间',
  `audit_remark` varchar(500) DEFAULT NULL COMMENT '审核意见',
  `apply_files_json` longtext COMMENT '报名附件JSON文本',
  `compare_files_json` longtext COMMENT '比选资料JSON文本',
  `dept_id` bigint DEFAULT NULL COMMENT '当前归属部门/学校',
  `create_by` varchar(64) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `del_flag` char(1) NOT NULL DEFAULT '0' COMMENT '删除标记，0正常 1删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_xfpt_supplier_apply_no` (`apply_no`),
  UNIQUE KEY `uk_xfpt_supplier_apply_notice_supplier` (`notice_id`,`supplier_id`),
  KEY `idx_xfpt_supplier_apply_status` (`notice_id`,`supplier_id`,`qualification_status`,`bid_stage_status`,`bid_result_status`),
  KEY `idx_xfpt_supplier_apply_dept` (`dept_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='供应商报名';
/*!40101 SET character_set_client = @saved_cs_client */;

