  `CREATE_BY` varchar(100) DEFAULT NULL,
  `DEL_FLAG` varchar(10) DEFAULT NULL,
  `NAME` varchar(100) DEFAULT NULL,
  `REMARK` varchar(100) DEFAULT NULL,
  `URL` varchar(255) DEFAULT NULL,
  `VIDEO_URL` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`ID`)
