CREATE TABLE `xfpt_supplier_message` (
  `ID` bigint NOT NULL,
  `SUPPLIER_NAME` varchar(255) DEFAULT NULL,
  `SUPPLIER_PHONE` varchar(255) DEFAULT NULL,
  `SUPPLIER_TYPE` varchar(255) DEFAULT NULL,
  `LEGAL_REPRESENTATIVE` varchar(255) DEFAULT NULL,
  `TURNOVER_TIME` timestamp NULL DEFAULT NULL,
  `STAFF_NUMBER` varchar(255) DEFAULT NULL,
  `ESTABLISHED_TIME` timestamp NULL DEFAULT NULL,
  `SUPPLIER_ADDRESS` varchar(255) DEFAULT NULL,
  `SUPPLIER_INTRODUCE` text,
  `EQUIPMENT_CONDITIONS` varchar(255) DEFAULT NULL,
  `BUSINESS_LICENSE` varchar(255) DEFAULT NULL,
  `CREATE_BY` varchar(255) DEFAULT NULL,
  `CREATE_TIME` timestamp NULL DEFAULT NULL,
  `UPDATE_BY` varchar(255) DEFAULT NULL,
  `UPDATE_TIME` timestamp NULL DEFAULT NULL,
  `REMARK` varchar(255) DEFAULT NULL,
  `REGISTERED_CAPITAL` varchar(100) DEFAULT NULL,
  `DEL_FLAG` varchar(100) DEFAULT '0',
  `INSURED_NUMBER` varchar(100) DEFAULT NULL,
  `BLACKLIST_STATUS` varchar(100) DEFAULT '0',
  `DEPT_ID` varchar(100) DEFAULT NULL,
  `DEPT_NAME` varchar(100) DEFAULT NULL,
  `ANCESTORS` varchar(100) DEFAULT NULL,
  `xypj` varchar(255) DEFAULT NULL,
  `violation_reason` text,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='供应商信息表';
