--
-- Table structure for table `xfpt_user_address`
--

DROP TABLE IF EXISTS `xfpt_user_address`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `xfpt_user_address` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` bigint NOT NULL COMMENT '家长用户ID',
  `receiver_name` varchar(100) NOT NULL COMMENT '收货人姓名',
  `receiver_phone` varchar(20) NOT NULL COMMENT '收货手机号',
  `province_name` varchar(50) DEFAULT NULL COMMENT '省',
  `city_name` varchar(50) DEFAULT NULL COMMENT '市',
  `district_name` varchar(50) DEFAULT NULL COMMENT '区县',
  `detail_address` varchar(500) NOT NULL COMMENT '详细地址',
  `address_type` char(1) NOT NULL COMMENT '地址类型，1家庭 2学校',
  `is_default` char(1) NOT NULL COMMENT '是否默认，0否 1是',
  `create_by` varchar(64) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `del_flag` char(1) NOT NULL DEFAULT '0' COMMENT '删除标记，0正常 1删除',
  PRIMARY KEY (`id`),
  KEY `idx_xfpt_user_address_user` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户收货地址';
/*!40101 SET character_set_client = @saved_cs_client */;

