  `apply_time` datetime DEFAULT NULL COMMENT '申请时间',
  `audit_user_id` bigint DEFAULT NULL COMMENT '审核人ID',
  `audit_user_name` varchar(100) DEFAULT NULL COMMENT '审核人姓名快照',
