  `pay_time` datetime DEFAULT NULL COMMENT '打款时间',
  `audit_remark` varchar(500) DEFAULT NULL COMMENT '审核备注',
  `finance_flow_id` bigint DEFAULT NULL COMMENT '关联资金流水ID',
  `create_by` varchar(64) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `del_flag` char(1) NOT NULL DEFAULT '0' COMMENT '删除标记，0正常 1删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_xfpt_withdraw_apply_no` (`withdraw_no`),
  KEY `idx_xfpt_withdraw_apply_supplier` (`supplier_id`,`status`),
  KEY `idx_xfpt_withdraw_apply_finance_flow` (`finance_flow_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='供应商提现申请';
